SELECT CAST(COUNT(CASE WHEN p.dod IS NOT NULL THEN 1 END) AS FLOAT) / NULLIF(COUNT(p.subject_id), 0) AS mortality_rate, CAST(COUNT(CASE WHEN p.dod IS NOT NULL AND p.diagnoses_icd.icd_code = '250.0' THEN 1 END) AS FLOAT) / NULLIF(COUNT(p.subject_id), 0) AS aki_rate, CAST(COUNT(CASE WHEN p.dod IS NOT NULL AND p.diagnoses_icd.icd_code = '370.0' THEN 1 END) AS FLOAT) / NULLIF(COUNT(p.subject_id), 0) AS ards_rate, MEDIAN(CASE WHEN p.dod IS NOT NULL THEN (p.dischtime - p.admittime) END) AS median_survival, percentile_cont(0.25) within GROUP (ORDER BY (p.dischtime - p.admittime)) AS p25_survival, percentile_cont(0.75) within GROUP (ORDER BY (p.dischtime - p.admittime)) AS p75_survival, percentile_cont(0.90) within GROUP (ORDER BY (p.dischtime - p.admittime)) AS p90_survival, percentile_cont(0.05) within GROUP (ORDER BY (p.dischtime - p.admittime)) AS min_survival FROM patients p JOIN admissions a ON p.subject_id = a.subject_id WHERE p.gender = 'F' AND p.anchor_age BETWEEN 59 AND 69 AND p.diagnoses_icd.icd_code = '415.999' AND a.hadm_id IN (SELECT hadm_id FROM admissions WHERE subject_id IN (SELECT subject_id FROM patients WHERE gender = 'F' AND anchor_age BETWEEN 59 AND 69 AND diagnoses_icd.icd_code = '415.999'));